const owners=o=>[o.source,o.panelOf,o.ownerId,o.attachment?.source,...(['image','text'].includes(o.type)?[o.clip]:[])].filter(Boolean);
export function mirrorDiagnostics(p){return clone(journals.get(p)||[]);}
function record(p,data){const log=journals.get(p)||[];log.push(data);if(log.length>200)log.shift();journals.set(p,log);}
export function mirrorAxis(p){return {id:'document-center',value:p.centerAxis??(p.document?.widthPx!==undefined?p.document.widthPx/2:350)};}
